(self.webpackChunksite=self.webpackChunksite||[]).push([[77],{1596:o=>{"use strict";o.exports=JSON.parse('{"slug":"pou-fashion","title":"Pou Fashion Simulator","authors":[{"name":"Ana Julia Thibes dos Santos","contact":"juju-thibes","contactType":"github","contactUrl":"https://github.com/juju-thibes"}],"date":1782950400000,"readme":"<p>The goal of the game is to dress up Pou for going out.</p>\\n<p>To dress Pou, you need to click on the clothes of his wardrobe, and if you want more clothes to chose from, you can click on the arrows on the inferior right corner to pass the pages of clothes.</p>\\n<p>You can also reset the outfit that Pou is wearing by clicking on the spiral arrow on the top left corner.</p>\\n<p>Also, you NEED to dress Pou to complete the game (he can\'t go out naked, ok?)</p>\\n<p>Have fun playing &#x3C;3</p>"}')}}]);